// Builds a one-tap link that opens this failed run in the Flowpocket phone app.
// Set SERVER to your n8n address without the scheme, exactly as saved in Flowpocket (e.g. n8n.example.com or 192.168.1.10:5678).
const SERVER = 'n8n.example.com';
const e = $input.first().json;
const id = e.execution?.id;
const wf = e.workflow?.name ?? 'workflow';
const node = e.execution?.lastNodeExecuted ?? 'unknown step';
const link = `flowpocket://execution/${id}?server=${encodeURIComponent(SERVER)}`;
return [{ json: { text: `n8n failure: ${wf} stopped at "${node}".\nOpen in Flowpocket: ${link}`, link, workflow: wf, executionId: id } }];
